        tileParams = BoomTileParams(
          core = BoomCoreParams(
            fetchWidth = 4,
            decodeWidth = 3,
            numRobEntries = 96,
            issueParams = Seq(
                IssueParams(issueWidth=2, numEntries=16, iqType=IQ_MEM, dispatchWidth=3),
                IssueParams(issueWidth=1, numEntries=16, iqType=IQ_UNQ, dispatchWidth=3, numSlowEntries=8),
                IssueParams(issueWidth=3, numEntries=16, iqType=IQ_ALU, dispatchWidth=3, numSlowEntries=8),
                IssueParams(issueWidth=1, numEntries=24, iqType=IQ_FP, dispatchWidth=3, numSlowEntries=12)),
            lsuWidth = 1,
            numIntPhysRegisters = 100,
            numFpPhysRegisters = 96,
            numIrfReadPorts = 6,
            numIrfBanks = 2,
            numFrfReadPorts = 3,
            numFrfBanks = 1,
            numLdqEntries = 24,
            numStqEntries = 24,
            maxBrCount = 16,
            numFetchBufferEntries = 24,
            numDCacheBanks = 1,
              enableSlowBTBRedirect = true,
              enableColumnALUIssue = true,
            ftq = FtqParameters(nEntries=32),
            bpdMaxMetaLength = 120,
            globalHistoryLength = 64,
            localHistoryLength = 32,
            localHistoryNSets = 128,
            branchPredictor = ((resp_in: BranchPredictionBankResponse, p: Parameters) => {
        val ubtb = Module(new MicroBTBBranchPredictorBank(BoomMicroBTBParams(nSets=256))(p))
        val bim = Module(new BIMBranchPredictorBank(BoomBIMParams(nSets=2048, singlePorted=true, nCols=4, slow=false))(p))
        val gbim = Module(new HBIMBranchPredictorBank(BoomHBIMParams(nSets=2048))(p))
        val lbim = Module(new HBIMBranchPredictorBank(BoomHBIMParams(nSets=2048, useLocal=true))(p))
        val btb = Module(new BTBBranchPredictorBank(BoomBTBParams(nSets=128, nWays=2, offsetSz=13, extendedNSets=128, useFlops=false))(p))
        val slowbtb = Module(new SlowBTBBranchPredictorBank(BoomSlowBTBParams(nSets=128, nWays=2, singlePorted=false))(p))
        val tourney = Module(new TourneyBranchPredictorBank(BoomTourneyBPDParams(nSets=128))(p))
        val tage = Module(new TageBranchPredictorBank(BoomTageParams(tableInfo=Seq(( 128,    2,   7), ( 128,    4,   7), ( 128,    8,   8), ( 128,   16,   8), ( 256,   32,   8), ( 256,   64,   9), ( 128,   80,   9), ( 128,   96,   9)), singlePorted=false))(p))
        val preds = Seq(ubtb, bim, gbim, lbim, btb, slowbtb, tourney, tage)
        preds.map(_.io := DontCare)

        ubtb.io.resp_in(0) := resp_in
        gbim.io.resp_in(0) := ubtb.io.resp
        lbim.io.resp_in(0) := ubtb.io.resp
        tourney.io.resp_in(0) := gbim.io.resp
        tourney.io.resp_in(1) := lbim.io.resp
        bim.io.resp_in(0) := tourney.io.resp
        btb.io.resp_in(0) := bim.io.resp
        slowbtb.io.resp_in(0) := btb.io.resp
        tage.io.resp_in(0) := slowbtb.io.resp
        (preds, tage.io.resp)
      }),
            fpu = Some(freechips.rocketchip.tile.FPUParams(sfmaLatency=4, dfmaLatency=4, divSqrt=true))
          ),
          dcache = Some(DCacheParams(rowBits=64, nSets=64, nWays=1, nMSHRs=2, nTLBWays=8)),
          icache = Some(ICacheParams(rowBits=64, nSets=64, nWays=4, fetchBytes=8)),
          tileId = idOffset
        ),
        crossingParams = RocketCrossingParams()
      )) ++ prev
    }
    case NumTiles => up(NumTiles) + 1
  })
)

